// Suscripciones de prueba. Cuando exista GET /api/alerts/subscriptions,
// este nodo se reemplaza por un HTTP Request con Header Auth.
const API_BASE = 'https://REEMPLAZAR.vercel.app'; // URL del deploy de Ashfield, sin / final

const subs = [
  {
    id: 'demo-pampa',
    name: 'Lote de prueba (pampa)',
    lat: -33.89, lon: -60.57,
    radius_km: 25,              // avisar si hay un foco a esta distancia o menos
    email: 'REEMPLAZAR@ejemplo.com', // a quién mandar el aviso
    country: 'AR',
  },
];

return subs.map(s => {
  const dLat = s.radius_km / 111;
  const dLon = s.radius_km / (111 * Math.cos(s.lat * Math.PI / 180));
  const bbox = [s.lon - dLon, s.lat - dLat, s.lon + dLon, s.lat + dLat]
    .map(v => v.toFixed(4)).join(',');
  return { json: { ...s, api_base: API_BASE,
    live_url: `${API_BASE}/api/live?window=24h&bbox=${bbox}` } };
});

// Para cada campo: focos de /api/live dentro del radio que no se avisaron antes.
const subs = $('Suscripciones').all().map(i => i.json);
const FIRE_NUMBER = { AR: '100', BR: '193', CL: '131', UY: '104', PY: '132', BO: '119' };
const SAT = { N: 'VIIRS S-NPP', N20: 'VIIRS NOAA-20', N21: 'VIIRS NOAA-21', T: 'MODIS Terra', A: 'MODIS Aqua' };
const DIRS = ['norte', 'noreste', 'este', 'sureste', 'sur', 'suroeste', 'oeste', 'noroeste'];

// Memoria de focos ya avisados (persiste solo en ejecuciones del flujo activo)
const memory = $getWorkflowStaticData('global');
memory.seen = memory.seen || [];
const seen = new Set(memory.seen);

const rad = d => d * Math.PI / 180;
function distKm(a, b, c, d) {
  const x = Math.sin(rad(c - a) / 2) ** 2 +
    Math.cos(rad(a)) * Math.cos(rad(c)) * Math.sin(rad(d - b) / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(x));
}
function direction(lat0, lon0, lat1, lon1) {
  const y = Math.sin(rad(lon1 - lon0)) * Math.cos(rad(lat1));
  const x = Math.cos(rad(lat0)) * Math.sin(rad(lat1)) -
    Math.sin(rad(lat0)) * Math.cos(rad(lat1)) * Math.cos(rad(lon1 - lon0));
  const deg = (Math.atan2(y, x) * 180 / Math.PI + 360) % 360;
  return DIRS[Math.round(deg / 45) % 8];
}

const out = [];
$input.all().forEach((item, i) => {
  const s = subs[i];
  const live = item.json;
  if (!s || live.mode !== 'points' || !Array.isArray(live.points)) return;
  const near = live.points
    .map(([lat, lon, frp, sat, acq]) => ({ lat, lon, frp, sat, acq,
      km: distKm(s.lat, s.lon, lat, lon) }))
    .filter(p => p.km <= s.radius_km)
    .filter(p => !seen.has(`${s.id}|${p.lat.toFixed(3)},${p.lon.toFixed(3)}|${p.acq}`))
    .sort((a, b) => a.km - b.km);
  if (!near.length) return;
  near.forEach(p => memory.seen.push(`${s.id}|${p.lat.toFixed(3)},${p.lon.toFixed(3)}|${p.acq}`));
  const p = near[0];
  const when = new Date(p.acq).toLocaleString('es-AR', {
    timeZone: 'America/Argentina/Buenos_Aires', day: 'numeric', month: 'numeric',
    hour: '2-digit', minute: '2-digit', hour12: false });
  const more = near.length > 1 ? ` (y ${near.length - 1} foco${near.length > 2 ? 's' : ''} más dentro de ${s.radius_km} km)` : '';
  const subject = `🔥 Ashfield: posible foco a ${p.km.toFixed(1).replace('.', ',')} km de «${s.name}»`;
  const message =
    `Ashfield: posible foco a ${p.km.toFixed(1).replace('.', ',')} km al ${direction(s.lat, s.lon, p.lat, p.lon)} ` +
    `de tu campo «${s.name}»${more}. Satélite ${SAT[p.sat] || p.sat}, ${when} (hora de Argentina).\n\n` +
    `Es una detección satelital, no un incendio confirmado. Si ves fuego o humo, llamá al ${FIRE_NUMBER[s.country] || '911'}.\n\n` +
    `Ver en el mapa: ${s.api_base}/app/\n\n` +
    `Coordenadas del foco: ${p.lat.toFixed(4)}, ${p.lon.toFixed(4)} · potencia radiativa ${p.frp} MW.\n` +
    `Recibís este aviso porque suscribiste el campo «${s.name}» a las alertas de Ashfield (radio de ${s.radius_km} km). ` +
    `Para dejar de recibirlas, respondé este correo con la palabra BAJA.`;
  out.push({ json: { subscription_id: s.id, email: s.email, subject, km: p.km, focos: near.length, message } });
});
memory.seen = memory.seen.slice(-1000);
return out;
